-- sq/build/cartridge.lua: the build of a workspace whose deliverable is a
-- cartridge (a kit, a package or a template), for sqmake. GENERATED by
-- {{template_id}} {{template_version}}: the template owns this file and replaces it on
-- update; build.lua, which includes it, is yours.
--
--   cartridge = {kind = "kit", id = "kit.fmt"}
--   include("sq/build/cartridge.lua")
--
--   sqmake          packs cartridge/ into dist/ID.sq with sqdrive, which
--                   refuses a manifest that is not JSON or lacks its id,
--                   version or kind: building is the check
--   sqmake install  copies cartridge/, exploded, into your own resources,
--                   ${XDG_DATA_HOME:-~/.local/share}/squared-pg/resources/KINDs/ID,
--                   where sqpg and square find it (New in sqIDE lists it)
--
-- sqdrive is the SDK's (pkg install sqdrive), as sqmake is.

local c = cartridge or error("sq/build/cartridge.lua: set cartridge = {kind = ..., id = ...} before including it")
local kind = c.kind or error("sq/build/cartridge.lua: cartridge.kind")
local id = c.id or error("sq/build/cartridge.lua: cartridge.id")

local out = "dist/" .. id .. ".sq"
target{out = out, ins = glob("cartridge/**/*"), desc = "pack " .. id, cmds = {
  {"mkdir", "-p", "dist"},
  {"rm", "-f", out},  -- sqdrive pack makes a new cartridge, never over one
  {c.sqdrive or "sqdrive", "pack", "cartridge", out},
}}
default(out)

-- Exploded, as every cartridge is to work on: an edit in cartridge/ and
-- another install, and the next sqpg run sees it.
local copy = [[
d="${XDG_DATA_HOME:-$HOME/.local/share}/squared-pg/resources/$1/$2"
rm -rf "$d" && mkdir -p "$d" && cp -R cartridge/. "$d/" && echo "installed $2: $d"
]]
verb("install", {needs = {out}, call = function()
  return exec{"sh", "-c", copy, "sh", kind .. "s", id}
end})
